            authorized = grant(assignabilityDecision.value === 'disable' ? 'DisableCommercialMarket' : 'EnableCommercialMarket', fields.market_id); break;
        case 'register':
            if (!workspace.value || !currentConfiguration.value?.catalog_reference_id || !currentConfiguration.value.denomination_code) return 'PREREQUISITE_MISSING';
            authorized = grant('RegisterCommercialScope', fields.scope_id, fields.workspace_public_id) && grant('RecordBeneficiaryBinding', fields.scope_id, fields.workspace_public_id) && grant('AssignCommercialMarket', fields.scope_id, fields.workspace_public_id, fields.configuration_id); break;
    }
    return authorized ? 'EXECUTABLE' : selectedMarket.value ? 'VISIBLE_BUT_READ_ONLY' : 'PREREQUISITE_MISSING';
});
const authorityCopy = computed(() => {
    if (!fields.market_id) return c('اختر السوق أولًا.', 'Select a market first.');
    if (props.freshAuthentication === false) return c('جدّد تسجيل الدخول قبل حفظ أي تغيير؛ انتهى التحقق الحديث.', 'Renew sign-in before saving a change; recent authentication has expired.');
    if (props.freshAuthentication === undefined) return c('لم تتأكد صلاحية التنفيذ من البيانات الحالية. حدّث الحالة والصلاحيات.', 'Execution authority cannot be confirmed from current data. Refresh state and permissions.');
    if (authority.value === 'VISIBLE_BUT_READ_ONLY') return c('عرض فقط؛ لا تتيح صلاحيتك هذا الإجراء على السوق أو المستفيد المختار.', 'Read only; your permissions do not allow this action for the selected market or beneficiary.');
    if (operation.value === 'assignability' && assignabilityDecision.value === 'select') {
        if (!catalogs.value.length) return c('لا يمكن السماح بتسجيل عملاء جدد: لم يوثّق مرجع تجاري معتمد لهذا السوق. أضف المرجع من الإجراءات المتقدمة ثم أكمل الإعداد.', 'New customer registrations cannot be enabled: this market has no recorded approved reference. Record the reference in advanced actions, then complete setup.');
        if (!completeConfigurations.value.length) return c('لا يوجد إعداد مكتمل بمرجع معتمد وعملة. أكمل إعدادات السوق قبل السماح بالتسجيل.', 'No complete configuration has both an approved reference and currency. Complete market settings before enabling registrations.');
        if (!completeConfigurations.value.some(conf => conf.id === fields.configuration_id)) return c('اختر الإعداد المكتمل الذي سيستخدمه العملاء الجدد.', 'Choose the complete configuration that new customers will use.');
    }
    if (operation.value === 'register' && authority.value === 'PREREQUISITE_MISSING') return currentConfiguration.value?.catalog_reference_id && currentConfiguration.value.denomination_code ? c('اختر مستفيدًا مصرحًا وتحقق من بياناته قبل تسجيله.', 'Choose an authorized beneficiary and verify their details before registration.') : c('يلزم إعداد مكتمل ومفعّل بمرجع معتمد وعملة قبل تسجيل المستفيد.', 'A complete, active configuration with an approved reference and currency is required before registering a beneficiary.');
    if (operation.value === 'catalog' && !fields.catalog_reference_id) return c('اختر المرجع المصرح لك بتوثيقه؛ يلزم مصدر اعتماد حقيقي.', 'Choose a reference you are authorized to record; a real approved source is required.');
    if (authority.value !== 'EXECUTABLE') return c('الإعداد الجديد غير متاح حاليًا. حدّث الحالة قبل المتابعة.', 'The new configuration is unavailable. Refresh state before continuing.');
    if (operation.value === 'configuration') return fields.catalog_reference_id && fields.denomination_code ? c('يمكن حفظ إصدار إعدادات جديد؛ السماح بتسجيل العملاء إجراء منفصل.', 'You may save a new configuration version; enabling customer registrations is a separate action.') : c('يمكن حفظ الإعداد غير المكتمل، لكنه لن يسمح بتسجيل العملاء حتى اكتمال المرجع المعتمد والعملة وتفعيله.', 'You may save incomplete settings, but customer registrations remain unavailable until the approved reference and currency are complete and activated.');
    return c('يمكن تنفيذ الإجراء وفق صلاحيتك الحالية.', 'This action is available under your current permissions.');
});
function labelConfiguration(conf: Configuration | undefined) { return conf ? `${c('إصدار', 'Version')} ${conf.version} · ${conf.denomination_code ?? c('عملة غير مثبتة', 'No denomination')} · ${conf.catalog_reference_id ? c('مرجع مثبت', 'Reference pinned') : c('مرجع غير مثبت', 'No reference')}` : c('لا يوجد إعداد متاح للإسناد', 'No assignable configuration'); }
function deliveryLabel(state: string) { const labels: Record<string, [string,string]> = { pending: ['بانتظار التسليم','Pending'], failed: ['تعذّر التسليم','Failed'], unknown: ['غير مؤكد','Unknown'], acknowledged: ['تم إقرار الحفظ','Acknowledged'] }; return labels[state.toLowerCase()] ? c(...labels[state.toLowerCase()]) : c('حالة غير معروفة','Unknown state'); }
function canRecover(item: typeof props.obligations[number]) { return props.freshAuthentication === true && !!item.target_id && grant('RetryOrRecoverExistingAuditDelivery', item.target_id, item.workspace_public_id ?? null); }
function descriptions(field: string) { return fieldErrors.value[field] ? `error-${field}` : undefined; }
function acknowledgeReconciliation() { if (!reconciled.value || busy.value) return; lifecycle.value = 'completed'; conflictReview.value = false; error.value = ''; newCommand(); }
function acknowledgeConflict() { if (!conflictReviewReady.value || busy.value) return; lifecycle.value = 'completed'; conflictReview.value = false; conflictReviewReady.value = false; error.value = ''; newCommand(); }
function refreshRecords() { router.reload({ only: ['markets','configurations','catalogReferences','targets','obligations','newConfigurationId','newMarketTargets','founderAccess','newCatalogReferenceId','freshAuthentication'] }); }
function focusResult() { document.getElementById('operation-result')?.focus(); }
</script>
<template>
    <Head :title="c('الإعداد التجاري', 'Commercial configuration')" />
