                        <ul class="commercial-records commercial-market-list"><li v-for="m in visibleMarkets" :key="m.id" :data-market-row="m.id"><div><strong>{{ m.country_code ? countryName(m) : m.label }}</strong><p>{{ marketStatus(m) }}</p></div><div class="commercial-buttons"><button type="button" class="admin-action" :data-manage-market="m.id" :aria-pressed="fields.market_id === m.id" :disabled="locked" @click="manageMarket(m.id)">{{ c('إدارة السوق', 'Manage market') }}</button><button type="button" class="admin-text-link" :data-hide-market="m.id" :disabled="locked" @click="hideMarket(m.id)">{{ c('إخفاء من قائمتي', 'Hide from my list') }}</button></div></li></ul>
                        <p v-if="!visibleMarkets.length" class="admin-description">{{ c('لا توجد أسواق ظاهرة في قائمتك.', 'No markets are visible in your list.') }}</p>
                        <details class="admin-detail"><summary>{{ c('تنظيم قائمتي والأسواق المخفية', 'My list and hidden markets') }} ({{ hiddenMarkets.length }})</summary><p class="admin-description">{{ c('الإخفاء ينظم قائمتك الشخصية على هذا المتصفح فقط؛ يبقى السوق متاحًا للآخرين. لإيقاف الاستخدام الجديد استخدم إجراء التفعيل أو الإيقاف.', 'Hiding organizes your personal list in this browser only; the market remains available to others. Use Activate or stop new usage to stop new registrations.') }}</p><ul class="commercial-records"><li v-for="m in hiddenMarkets" :key="m.id"><strong>{{ m.label }}</strong><button type="button" class="admin-action" :data-restore-market="m.id" :disabled="locked" @click="restoreMarket(m.id)">{{ c('إعادة إلى قائمتي', 'Restore to my list') }}</button></li></ul></details>
                        <div v-if="selectedMarket" class="commercial-current"><h3>{{ selectedMarket.country_code ? countryName(selectedMarket) : selectedMarket.label }}</h3><p>{{ c('الدولة', 'Country') }}: {{ countryName(selectedMarket) }} · {{ c('عملة أحدث إعداد', 'Latest configured currency') }}: {{ latestConfiguration?.denomination_code ? currencyName(latestConfiguration.denomination_code) : c('غير محددة', 'Not set') }}</p><p>{{ marketStatus(selectedMarket) }}</p><div class="commercial-buttons"><button type="button" class="admin-action admin-action-primary" data-operation="configuration" :disabled="locked" @click="chooseOperation('configuration')">{{ c('تعديل إعدادات السوق', 'Edit market settings') }}</button><button type="button" class="admin-action" data-primary-availability="true" :disabled="locked" @click="openAvailability">{{ selectedMarket.configuration_id ? c('إيقاف تسجيل عملاء جدد', 'Stop new customer registrations') : c('السماح بتسجيل عملاء جدد', 'Allow new customer registrations') }}</button></div></div><p v-else class="admin-description">{{ fields.market_id ? c('هوية جديدة مشمولة بالمنحة؛ لم تسجل بعد.', 'Authorized new identity; not yet recorded.') : c('اختر سوقًا تجاريًا لعرض إعداداته ومراجعه.', 'Select a commercial market to view its configuration and references.') }}</p>
                    </section>
                    <section v-if="selectedMarket && editing && operation === 'configuration'" class="admin-section" aria-labelledby="settings-heading"><header class="admin-section-heading"><h2 id="settings-heading">{{ c('تعديل إعدادات السوق', 'Edit market settings') }}</h2><p class="admin-description" :data-authority="authority">{{ authorityCopy }}</p></header><div class="commercial-fields"><div class="admin-field"><label for="commercial-catalog_reference_id">{{ c('المرجع التجاري المعتمد', 'Approved commercial reference') }}</label><select id="commercial-catalog_reference_id" v-model="fields.catalog_reference_id"><option value="">{{ c('لم يوثّق مرجع معتمد', 'No approved reference recorded') }}</option><option v-for="reference in catalogs" :key="reference.id" :value="reference.id">{{ reference.approval_reference }} · {{ reference.catalog_version }}</option></select><p class="admin-description" v-if="!catalogs.length">{{ c('أضف مرجعًا حقيقيًا معتمدًا من الإجراءات المتقدمة لإكمال الإعداد. حفظ العملة وحدها لا يفعّل السوق.', 'Record a real approved reference in advanced actions to complete setup. Saving currency alone does not activate the market.') }}</p></div><div class="admin-field"><label for="commercial-denomination_code">{{ c('عملة السوق', 'Market currency') }}</label><select id="commercial-denomination_code" v-model="fields.denomination_code"><option value="">{{ c('اختر العملة', 'Select currency') }}</option><option v-for="currency in currencyOptions" :key="currency" :value="currency">{{ currencyName(currency) }}</option></select></div><template v-for="field in ['catalog_reference_id','denomination_code','configuration_id','reason_code']" :key="field"><p v-if="fieldErrors[field]" :id="`error-${field}`" class="admin-error">{{ fieldErrors[field].join(' ') }}</p></template></div><button type="submit" class="admin-action admin-action-primary" :disabled="busy || authority !== 'EXECUTABLE'">{{ c('حفظ إعدادات السوق', 'Save market settings') }}</button></section>
                    <details id="commercial-advanced" class="admin-disclosure" :open="advancedOpen" @toggle="toggleAdvanced"><summary>{{ c('إجراءات متقدمة', 'Advanced actions') }}</summary><div class="admin-disclosure-body">
                        <div class="commercial-buttons" aria-label="Market actions"><button v-for="(name, key) in visibleOperationNames" :key="key" type="button" class="admin-action" :data-operation="key" :aria-pressed="operation === key" :disabled="locked" @click="chooseOperation(key)">{{ c(...name!) }}</button></div>
                        <div v-if="operation === 'market' && !founderAccess" class="admin-field"><label for="commercial-market_id">{{ c('السوق الجديد المُعدّ لك', 'New market prepared for you') }}</label><select id="commercial-market_id" v-model="fields.market_id" :aria-describedby="descriptions('market_id')" :aria-invalid="!!fieldErrors.market_id"><option value="">{{ c('اختر السوق المُعدّ', 'Select a prepared market') }}</option><option v-for="m in marketOptions" :key="m.id" :value="m.id">{{ m.label }}</option></select></div><p v-if="fieldErrors.market_id" id="error-market_id" class="admin-error">{{ fieldErrors.market_id.join(' ') }}</p>
                    <section v-if="fields.market_id && editing && operation !== 'configuration'" class="admin-section" aria-labelledby="operation-heading"><header class="admin-section-heading"><h2 id="operation-heading">{{ c(...operationNames[operation]) }}</h2><p class="admin-description">{{ setupGuidance }}</p><p v-if="freshAuthentication === false" class="admin-action-error">{{ c('يلزم تسجيل دخول حديث قبل التنفيذ. يمكنك مراجعة الأسواق والإعدادات الآن.', 'A recent login is required to execute. You can review markets and setup now.') }}</p><p class="admin-description" :data-authority="authority">{{ authorityCopy }}</p></header>
                        <div class="commercial-fields">
                            <div v-if="operation === 'assignability'" class="admin-field"><label for="assignability-decision">{{ c('قرار الإسناد', 'Assignability decision') }}</label><select id="assignability-decision" v-model="assignabilityDecision"><option value="select">{{ c('السماح بتسجيل عملاء جدد', 'Allow new customer registrations') }}</option><option value="disable">{{ c('إيقاف تسجيل عملاء جدد', 'Stop new customer registrations') }}</option></select><p class="admin-description">{{ c('هذا القرار يؤثر في التسجيلات الجديدة فقط.', 'This decision affects new registrations only.') }}</p></div>
                            <div v-if="operation === 'assignability' && assignabilityDecision === 'select'" class="admin-field"><label for="commercial-configuration_id">{{ c('الإعداد الجديد المختار', 'Selected new configuration') }}</label><select id="commercial-configuration_id" v-model="fields.configuration_id" :aria-describedby="descriptions('configuration_id')" :aria-invalid="!!fieldErrors.configuration_id"><option value="">{{ c('اختر إعدادًا جديدًا', 'Select a new configuration') }}</option><option v-for="conf in completeConfigurations" :key="conf.id" :value="conf.id">{{ labelConfiguration(conf) }}</option></select><p v-if="fieldErrors.configuration_id" id="error-configuration_id" class="admin-error">{{ fieldErrors.configuration_id.join(' ') }}</p></div>
                            <div v-if="operation === 'catalog'" class="admin-field"><label for="commercial-catalog_reference_id">{{ c('المرجع المصرح بتوثيقه', 'Reference authorized for recording') }}</label><select id="commercial-catalog_reference_id" v-model="fields.catalog_reference_id"><option value="">{{ c('اختر الهوية المصرح بها', 'Select an authorized identity') }}</option><option v-for="(target, index) in authorizedReferences" :key="target.version_id!" :value="target.version_id">{{ c('مرجع مصرح', 'Authorized reference') }} {{ index + 1 }}</option></select><p class="admin-description">{{ c('الخيارات محددة بصلاحيتك؛ اختر المرجع المعتمد.', 'Your permissions determine these choices; select the approved reference.') }}</p></div>
                            <div v-if="operation === 'register'" class="admin-field"><label for="scope-select">{{ c('المستفيد المصرح بتسجيله', 'Beneficiary authorized for registration') }}</label><select id="scope-select" v-model="scopeSelection" @change="selectScope"><option value="">{{ c('اختر المستفيد', 'Select beneficiary') }}</option><option v-for="(target, index) in scopeTargets" :key="target.target_id + target.workspace_public_id" :value="scopeKey(target)">{{ beneficiaryNames[scopeKey(target)] ?? `${c('مستفيد مصرح', 'Authorized beneficiary')} ${index + 1}` }}</option></select><p v-if="workspace" class="commercial-beneficiary">{{ workspace.name }}</p></div>
                            <div v-for="field in decisionFields.filter(field => !['catalog_identity', 'source_sha256', 'denomination_code'].includes(field))" :key="field" class="admin-field"><label :for="`commercial-${field}`">{{ c(...fieldNames[field]) }}</label><input :id="`commercial-${field}`" v-model="fields[field]" :dir="field === 'label' ? undefined : 'ltr'" :aria-describedby="descriptions(field)" :aria-invalid="!!fieldErrors[field]" /><p v-if="fieldErrors[field]" :id="`error-${field}`" class="admin-error">{{ fieldErrors[field].join(' ') }}</p></div>
                            <details v-if="operation === 'catalog'" class="commercial-source admin-detail" :open="!!fieldErrors.catalog_identity || !!fieldErrors.source_sha256"><summary>{{ c('بيانات المصدر المعتمد', 'Approved source details') }}</summary><p class="admin-description">{{ c('انسخ معرّف المصدر وبصمة الملف من مستند اعتماد المرجع كما هما؛ لا تنشئ قيمًا بديلة.', 'Copy the source identifier and file checksum exactly from the reference approval document; do not invent replacements.') }}</p><div v-for="field in ['catalog_identity', 'source_sha256']" :key="field" class="admin-field"><label :for="`commercial-${field}`">{{ c(...fieldNames[field]) }}</label><input :id="`commercial-${field}`" v-model="fields[field]" dir="ltr" :aria-describedby="descriptions(field)" :aria-invalid="!!fieldErrors[field]" /><p v-if="fieldErrors[field]" :id="`error-${field}`" class="admin-error">{{ fieldErrors[field].join(' ') }}</p></div></details>
                            <p v-if="fieldErrors.reason_code" class="admin-error">{{ fieldErrors.reason_code.join(' ') }}</p>
                        </div><button type="submit" class="admin-action admin-action-primary" :disabled="busy || authority !== 'EXECUTABLE'">{{ c(...actionButtonNames[operation]) }}</button>
                    </section>
                    </div></details>
                    <details v-if="fields.market_id" id="commercial-history" class="admin-disclosure"><summary>{{ c('المراجع المعتمدة وسجل الإعدادات', 'Approved references and configuration history') }}</summary><div class="admin-disclosure-body">
                    <section v-if="fields.market_id" class="admin-section" aria-labelledby="references-heading"><header class="admin-section-heading"><h2 id="references-heading">{{ c('المراجع التجارية المعتمدة', 'Approved commercial references') }}</h2><p class="admin-description">{{ c('مراجع محددة الإصدار تثبت منشأ الإعدادات.', 'Versioned references preserving configuration provenance.') }}</p></header><p v-if="!catalogs.length" class="admin-description">{{ c('لا توجد مراجع متاحة للعرض لهذا السوق.', 'No references are available to read for this market.') }}</p><ul class="commercial-records"><li v-for="r in catalogs" :key="r.id"><div><strong>{{ r.approval_reference }}</strong><p>{{ c('إصدار المرجع', 'Reference version') }} {{ r.catalog_version }}</p><p v-if="r.recorded_at">{{ c('تاريخ التسجيل', 'Recorded at') }}: <time>{{ r.recorded_at }}</time></p></div><details class="admin-detail"><summary>{{ c('منشأ المرجع', 'Reference provenance') }}</summary><dl dir="ltr"><dt>Catalog identity</dt><dd>{{ r.catalog_identity }}</dd><dt>Reference identity</dt><dd>{{ r.id }}</dd><dt>Market identity</dt><dd>{{ r.market_id }}</dd><dt>SHA-256</dt><dd>{{ r.source_sha256 }}</dd></dl></details></li></ul></section>
                    <section v-if="fields.market_id" class="admin-section" aria-labelledby="configurations-heading"><header class="admin-section-heading"><h2 id="configurations-heading">{{ c('إصدارات الإعدادات', 'Configuration versions') }}</h2><p class="admin-description">{{ c('سجل الإصدارات الثابتة؛ التسجيلات السابقة محفوظة.', 'Immutable version history; previous registrations are preserved.') }}</p></header><p v-if="!configurations.length" class="admin-description">{{ c('لا توجد إصدارات متاحة للعرض.', 'No configuration versions are available to read.') }}</p><ul class="commercial-records"><li v-for="conf in configurations" :key="conf.id"><div><strong>{{ labelConfiguration(conf) }}</strong><p>{{ conf.id === selectedMarket?.configuration_id ? c('الإعداد المتاح حاليًا للإسناد', 'Currently assignable configuration') : c('إصدار محفوظ', 'Recorded version') }}</p><p>{{ conf.catalog_reference_id && conf.denomination_code && catalogs.some(r => r.id === conf.catalog_reference_id) ? c('المرجع والعملة مثبتان في البيانات المقروءة.', 'Reference and denomination are pinned in readable data.') : c('غير مكتمل أو لا تتوفر بيانات قراءة كافية للتحقق.', 'Incomplete or insufficient readable data to verify.') }}</p></div><details class="admin-detail"><summary>{{ c('هوية الإصدار', 'Version identity') }}</summary><dl dir="ltr"><dt>Configuration identity</dt><dd>{{ conf.id }}</dd><dt>Configuration version</dt><dd>{{ conf.version }}</dd><dt>Catalog reference</dt><dd>{{ conf.catalog_reference_id ?? '—' }}</dd></dl></details></li></ul></section>
                    </div></details>
                </fieldset>
            </form>
            <section v-if="lifecycle !== 'idle'" id="operation-result" tabindex="-1" aria-labelledby="result-heading" class="admin-section" aria-live="polite"><header class="admin-section-heading"><h2 id="result-heading">{{ c('أثر العملية', 'Operation effect') }}</h2></header><p>{{ lifecycle === 'inflight' ? c('الأمر قيد التنفيذ.', 'Command in flight.') : lifecycle === 'uncertain' ? c('النتيجة غير مؤكدة. محفوظ معرّف الطلب وحمولته الأصلية؛ احسمه قبل عملية أخرى.', 'Outcome uncertain. The original command identity and payload are preserved; reconcile it before another operation.') : lifecycle === 'completed' ? c('أكد الخادم نتيجة العملية.', 'The server confirmed the operation result.') : c('لا توجد عملية قيد التنفيذ.', 'No command is in flight.') }}</p><p v-if="result">{{ c(...operationNames[original?.operation ?? operation]) }}<span v-if="props.markets.find(m => m.id === original?.input.market_id)"> · {{ props.markets.find(m => m.id === original?.input.market_id)?.label }}</span></p><p v-if="lifecycle === 'completed' && original?.operation === 'register'" class="admin-description">{{ c('يثبت السياق فقط؛ الاتفاق والمبلغ غير مثبتين.', 'Context only; agreement and amount remain unknown.') }}</p><p v-if="lifecycle === 'uncertain' || conflictReview" dir="ltr" class="commercial-id">Command {{ command }}</p><details v-else class="admin-detail"><summary>{{ c('هوية الأمر', 'Command identity') }}</summary><p dir="ltr" class="commercial-id">{{ command }}</p></details><div class="commercial-buttons"><button v-if="lifecycle === 'uncertain'" type="button" class="admin-action" :disabled="busy || conflictReview" @click="execute">{{ c('إعادة الطلب الأصلي دون تغيير', 'Retry the unchanged original request') }}</button><button v-if="conflictReviewReady" data-conflict-review="true" type="button" class="admin-action" :disabled="busy" @click="acknowledgeConflict">{{ c('راجعت الحالة المحدثة — بدء أمر جديد', 'I reviewed the refreshed state — start a new command') }}</button><button v-if="reconciled" type="button" class="admin-action" :disabled="busy" @click="acknowledgeReconciliation">{{ c('راجعت الإيصال والحالة — بدء عملية جديدة', 'I reviewed the receipt and state — start a new operation') }}</button><button type="button" class="admin-action" :disabled="locked" @click="newCommand">{{ c('بدء عملية جديدة', 'Start a new operation') }}</button></div><details v-if="result" class="admin-detail"><summary>{{ c('نتيجة الأمر التقنية', 'Technical command result') }}</summary><pre>{{ JSON.stringify(result, null, 2) }}</pre></details></section>
